import styled from 'styled-components';

export const StyledSegmentedControl = styled.div({
  display: 'flex',
  alignItems: 'center',
  gap: '16px',
});

export const StyledSegmentedControlItems = styled.div({
  display: 'flex',
  maxHeight: '2.5rem',
  minHeight: '2.5rem',
  backgroundColor: '#0000000d',
  width: 'max-content',
  borderRadius: '624.9375rem',
});

export const StyledSegmentedControlButton = styled.button<{ active: boolean }>(
  {
    cursor: 'pointer',
    display: 'flex',
    alignItems: 'center',
    justifyContent: 'center',
    minWidth: '187px',
    maxHeight: '2.5rem',
    border: 'none',
    borderRadius: '2rem',
    padding: '0 16px',
    fontSize: '0.875rem',
    lineHeight: '1rem',
    fontWeight: '500',
    fontFamily: 'Work Sans',
  },
  (props) => ({
    color: props.active ? '#141414' : '#0000008c',
    backgroundColor: props.active ? '#ffffff' : 'transparent',
    boxShadow: props.active
      ? '0rem 0.125rem 0.5rem 0rem rgba(0, 0, 0, .08)'
      : 'none',
  }),
);
